.ds-scheme-plate { --_field: var(--sem-flowering-summer-bg); --_field-deep: color-mix(in srgb, var(--sem-flowering-summer-bg) 60%, var(--sem-flowering-summer-fg)); --_ink: var(--sem-flowering-summer-fg); position: relative; overflow: hidden; display: flex; flex-direction: column; inline-size: 20rem; min-block-size: 18rem; text-align: start; background: var(--color-white); border: none; border-radius: var(--radius-m); cursor: pointer; box-shadow: 0 1px 0 color-mix(in srgb, var(--color-sand-line) 55%, transparent); transition: box-shadow 0.4s cubic-bezier(0.16,1,0.3,1), transform 0.4s cubic-bezier(0.16,1,0.3,1); }
.ds-scheme-plate__field { position: relative; overflow: hidden; flex: none; block-size: 8rem; background: var(--_field); border-block-end: 1px solid color-mix(in srgb, var(--_field-deep) 65%, transparent); transition: background-color 0.4s cubic-bezier(0.16,1,0.3,1); }
.ds-scheme-plate__field::after { content: ""; position: absolute; inset: 0; pointer-events: none; background: linear-gradient(172deg, transparent 50%, color-mix(in srgb, var(--_ink) 12%, transparent)); }
.ds-scheme-plate__mark { position: absolute; inset-block-end: -1.5rem; inset-inline-end: 0.5rem; inline-size: 8.5rem; block-size: 8.5rem; color: var(--_ink); opacity: 0.4; transition: opacity 0.4s cubic-bezier(0.16,1,0.3,1), transform 520ms cubic-bezier(0.16,1,0.3,1); }
.ds-scheme-plate__body { display: flex; flex: 1; flex-direction: column; gap: 0.5rem; padding: 1rem 1.5rem 1.5rem; }
.ds-scheme-plate__title { font-family: var(--font-display); font-weight: 600; font-size: clamp(1.202rem, 0.406vw + 1.130rem, 1.563rem); line-height: 1.15; color: var(--color-ink); }
.ds-scheme-plate__note { font-family: var(--font-sans); font-size: clamp(0.813rem, 0.092vw + 0.797rem, 0.894rem); line-height: 1.5; color: var(--_ink); max-inline-size: 24ch; }
.ds-scheme-plate__go { display: inline-flex; align-items: center; gap: 0.25rem; margin-block-start: auto; padding-block-start: 0.5rem; font-family: var(--font-mono); font-size: 0.8rem; font-weight: 500; letter-spacing: 0.14em; text-transform: uppercase; color: var(--_ink); }
.ds-scheme-plate__go span { transition: transform 0.4s cubic-bezier(0.16,1,0.3,1); }
.ds-scheme-plate:hover { box-shadow: 0 8px 24px rgba(0,0,0,0.15); transform: translateY(-2px); }
.ds-scheme-plate:hover .ds-scheme-plate__field { background: var(--_field-deep); }
.ds-scheme-plate:hover .ds-scheme-plate__mark { opacity: 0.52; transform: scale(1.06); }
.ds-scheme-plate:hover .ds-scheme-plate__go span { transform: translateX(0.25rem); }
.ds-scheme-plate:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--color-paper), 0 0 0 4px var(--color-p-lavender), 0 8px 24px rgba(0,0,0,0.15); }
@media (prefers-reduced-motion: reduce) { .ds-scheme-plate, .ds-scheme-plate__field, .ds-scheme-plate__mark, .ds-scheme-plate__go span { transition: none; } .ds-scheme-plate:hover { transform: none; } .ds-scheme-plate:hover .ds-scheme-plate__mark, .ds-scheme-plate:hover .ds-scheme-plate__go span { transform: none; } }

.ds-schedule { --_accent: var(--sem-flowering-spring-fg); --_accent-wash: var(--sem-flowering-spring-bg); inline-size: 26rem; background: var(--color-white); border: 1px solid var(--sem-border-color); border-radius: var(--radius-m); overflow: hidden; }
.ds-schedule__head { display: flex; align-items: baseline; justify-content: space-between; gap: 1rem; padding: 0.5rem 1rem; background: color-mix(in srgb, var(--_accent-wash) 68%, var(--color-white)); border-block-end: 1px solid color-mix(in srgb, var(--_accent) 22%, var(--sem-border-color)); }
.ds-schedule__label, .ds-schedule__count { font-family: var(--font-mono); font-size: 0.8rem; font-weight: 500; letter-spacing: 0.14em; text-transform: uppercase; }
.ds-schedule__label { color: var(--_accent); }
.ds-schedule__count { color: color-mix(in srgb, var(--_accent) 78%, transparent); }
.ds-schedule__rows { list-style: none; margin: 0; padding: 0; }
.ds-schedule__row { display: grid; grid-template-columns: 1.75rem 1fr 2.75rem; align-items: center; gap: 0.5rem; min-block-size: 3.25rem; padding-inline: 1rem; border-block-end: 1px solid color-mix(in srgb, var(--sem-border-color) 70%, transparent); }
.ds-schedule__row:last-child { border-block-end: none; }
.ds-schedule__no { display: inline-flex; align-items: center; justify-content: center; inline-size: 1.75rem; block-size: 1.75rem; border-radius: 50%; background: var(--_accent); color: var(--color-r-white); font-family: var(--font-mono); font-size: 0.8rem; font-variant-numeric: tabular-nums; }
.ds-schedule__name { min-inline-size: 0; font-family: var(--font-display); font-size: clamp(1.042rem, 0.234vw + 1rem, 1.25rem); line-height: 1.3; color: var(--color-ink); overflow-wrap: break-word; }
.ds-schedule__remove { display: inline-flex; align-items: center; justify-content: center; inline-size: 2.75rem; block-size: 2.75rem; border: none; background: none; color: var(--color-ink-soft); border-radius: 50%; cursor: pointer; transition: background-color 0.4s ease, color 0.4s ease; }
.ds-schedule__remove:hover { background: var(--color-y-yellow); color: var(--color-n-deep-grey); }
.ds-schedule__remove:focus-visible { outline: 2px solid var(--color-b-cyan); outline-offset: 1px; }
.ds-schedule__row--ghost { border-block-end-style: dashed; }
.ds-schedule__row--ghost .ds-schedule__no { background: transparent; border: 1px dashed color-mix(in srgb, var(--_accent) 45%, transparent); color: color-mix(in srgb, var(--_accent) 55%, transparent); }
.ds-schedule__row--ghost .ds-schedule__name { font-family: var(--font-sans); font-size: 0.9rem; font-style: italic; color: var(--color-ink-soft); }

.ds-chat { display: flex; flex-direction: column; gap: 16px; }
.ds-chat__msg { display: flex; flex-direction: column; gap: 4px; max-inline-size: min(100%, 42rem); }
.ds-chat__msg--assistant { align-self: flex-start; align-items: flex-start; }
.ds-chat__msg--user { align-self: flex-end; align-items: flex-end; }
.ds-chat__from { display: inline-flex; align-items: center; gap: 4px; font-family: var(--font-mono); font-size: 0.8rem; font-weight: 500; letter-spacing: 0.14em; text-transform: uppercase; color: var(--color-ink-soft); }
.ds-chat__avatar { flex: none; inline-size: 1.25rem; block-size: 1.25rem; color: var(--color-r-marigold); }
.ds-chat__bubble { padding: 8px 16px; line-height: 1.55; font-size: clamp(0.909rem, 0.102vw + 0.891rem, 1rem); border-radius: 8px; overflow-wrap: break-word; }
.ds-chat__msg--assistant .ds-chat__bubble { color: var(--color-n-deep-grey); background: var(--color-paper-deep); border-end-start-radius: 2px; }
.ds-chat__msg--user .ds-chat__bubble { color: var(--color-n-deep-grey); background: var(--color-white); border: 1px solid var(--sem-border-color); border-end-end-radius: 2px; }

.ds-typing { align-self: flex-start; display: inline-flex; gap: 0.25rem; align-items: center; padding: 8px 16px; background: var(--color-paper-deep); border-radius: 8px; border-end-start-radius: 2px; }
.ds-typing span { inline-size: 0.375rem; block-size: 0.375rem; border-radius: 50%; background: var(--color-ink-soft); animation: ds-typing 1.2s ease infinite; }
.ds-typing span:nth-child(2) { animation-delay: 0.15s; }
.ds-typing span:nth-child(3) { animation-delay: 0.3s; }
@keyframes ds-typing { 0%, 60%, 100% { opacity: 0.3; transform: translateY(0); } 30% { opacity: 1; transform: translateY(-0.125rem); } }
@media (prefers-reduced-motion: reduce) { .ds-typing span { animation: none; opacity: 0.55; } }

.ds-composer { display: flex; align-items: flex-end; gap: 8px; }
.ds-composer__input { flex: 1; min-inline-size: 0; resize: none; padding: 8px 16px; font: inherit; font-size: clamp(0.813rem, 0.092vw + 0.797rem, 0.894rem); line-height: 1.5; color: var(--color-ink); background: var(--color-paper); border: 1px solid var(--color-sand-line); border-radius: 8px; caret-color: var(--color-r-marigold); field-sizing: content; max-block-size: 8rem; overflow-y: auto; }
.ds-composer__input::placeholder { color: color-mix(in srgb, var(--color-ink-soft) 60%, transparent); }
.ds-composer__input:focus-visible { outline: none; border-color: var(--color-r-marigold); box-shadow: 0 0 0 2px var(--color-r-marigold); }
.ds-composer__send { flex: none; display: inline-flex; align-items: center; justify-content: center; inline-size: 2.75rem; block-size: 2.75rem; color: var(--color-r-white); background: var(--color-r-marigold); border: none; border-radius: 50%; cursor: pointer; transition: background-color 0.4s ease; }
.ds-composer__send:hover { background: var(--color-o-vermillion); }
.ds-composer__send:disabled { opacity: 0.4; cursor: not-allowed; }
.ds-composer__send:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--color-paper), 0 0 0 4px var(--color-p-lavender); }

.ds-sheet { --_accent: var(--sem-flowering-spring-fg); --_accent-wash: var(--sem-flowering-spring-bg); --_figure-measure: 22rem; inline-size: 26rem; background: var(--color-white); border: 1px solid var(--sem-border-color); border-radius: var(--radius-m, 4px); overflow: hidden; }
.ds-sheet__head { display: flex; align-items: baseline; justify-content: space-between; gap: 1rem; padding: 0.5rem 1rem; background: color-mix(in srgb, var(--_accent-wash) 60%, var(--color-white)); border-block-end: 1px solid color-mix(in srgb, var(--_accent) 20%, var(--sem-border-color)); }
.ds-sheet__label, .ds-sheet__count { font-family: var(--font-mono), ui-monospace, monospace; font-size: 0.8rem; font-weight: 500; letter-spacing: 0.14em; text-transform: uppercase; }
.ds-sheet__label { color: var(--_accent); }
.ds-sheet__count { color: color-mix(in srgb, var(--_accent) 78%, transparent); }
.ds-sheet__elevation { display: block; inline-size: 100%; max-inline-size: var(--_figure-measure); margin-inline: auto; block-size: auto; padding: 0.5rem 1rem 0; box-sizing: border-box; }
.ds-sheet__ground { fill: none; stroke: color-mix(in srgb, var(--_accent) 40%, var(--sem-border-color)); stroke-width: 1; stroke-linecap: round; }
.ds-sheet__plant path { fill: none; stroke: var(--_accent); stroke-width: 1.4; stroke-linecap: round; stroke-linejoin: round; stroke-dasharray: 1; stroke-dashoffset: 0; animation: ds-sheet-draw 0.8s cubic-bezier(0.16, 1, 0.3, 1) backwards; animation-delay: var(--_delay, 0s); }
.ds-sheet__plant circle { fill: var(--_accent); animation: ds-sheet-dot 0.4s ease backwards; animation-delay: calc(var(--_delay, 0s) + 0.4s); }
.ds-sheet__ghost path { fill: none; stroke: color-mix(in srgb, var(--_accent) 45%, transparent); stroke-width: 1.2; stroke-linecap: round; stroke-dasharray: 0.035 0.045; }
.ds-sheet__year { display: flex; gap: 4px; max-inline-size: var(--_figure-measure); margin-inline: auto; padding: 4px 1rem 0.5rem; }
.ds-sheet__month { position: relative; flex: 1; min-inline-size: 0; padding-block: 0.25rem; text-align: center; font-family: var(--font-inter), sans-serif; font-size: 0.73rem; color: var(--color-ink-soft); background: var(--color-paper-deep); border-radius: 2px; }
.ds-sheet__month--spring { color: var(--sem-flowering-spring-fg); background: var(--sem-flowering-spring-bg); }
.ds-sheet__month--early-summer { color: var(--sem-flowering-early-summer-fg); background: var(--sem-flowering-early-summer-bg); }
.ds-sheet__month--summer { color: var(--sem-flowering-summer-fg); background: var(--sem-flowering-summer-bg); }
.ds-sheet__month--autumn { color: var(--sem-flowering-autumn-fg); background: var(--sem-flowering-autumn-bg); }
.ds-sheet__month--now::after { content: ""; position: absolute; inset-inline: 35%; inset-block-end: 0; block-size: 2px; border-radius: 2px; background: var(--_accent); }
@keyframes ds-sheet-draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
@keyframes ds-sheet-dot { from { opacity: 0; } to { opacity: 1; } }
@media (prefers-reduced-motion: reduce) { .ds-sheet__plant path, .ds-sheet__plant circle { animation: none; } }
